  MagicBgpConfig* = ref object of RootObj
    customer_asn*: int32
      ## ASN used on the customer end of the BGP session
    export_filter_id*: Option[string]
      ## ID of the BGP filter profile applied to routes advertised to the customer.
    extra_prefixes*: Option[seq[string]]
      ## Prefixes in this list will be advertised to the customer device, in addition to
      ## the routes in the Magic routing table.
    import_filter_id*: Option[string]
      ## ID of the BGP filter profile applied to routes received from the customer.
    md5_key*: Option[string]
      ## MD5 key to use for session authentication.
      ##
      ## Note that *this is not a security measure*. MD5 is not a valid security
      ## mechanism, and the
      ## key is not treated as a secret value. This is *only* supported for preventing
      ## misconfiguration, not for defending against malicious attacks.
      ##
      ## The MD5 key, if set, must be of non-zero length and consist only of the
      ## following types of
      ## character:
      ##
      ## * ASCII alphanumerics: `[a-zA-Z0-9]`
      ## * Special characters in the set `'!@#$%^&*()+[]{}<>/.,;:_-~`= \|`
      ##
      ## In other words, MD5 keys may contain any printable ASCII character aside from
      ## newline (0x0A),
      ## quotation mark (`"`), vertical tab (0x0B), carriage return (0x0D), tab (0x09),
      ## form feed
      ## (0x0C), and the question mark (`?`). Requests specifying an MD5 key with one or
      ## more of
      ## these disallowed characters will be rejected.

  MagicBgpFilterMatchAction* = enum
    ## Action to take when a route matches one of the targets in this profile
    allow = "allow"
    deny = "deny"

  MagicBgpFilterProfile* = ref object of RootObj
    created_on*: Option[string]
    description*: string
      ## Description of the filter profile
    id*: MagicSchemasIdentifier
    match_action*: MagicBgpFilterMatchAction
    modified_on*: Option[string]
    name*: string
      ## Friendly name for the filter profile
    targets*: seq[string]
      ## List of CIDR prefixes. Each entry may carry an optional suffix that specifies
      ## which prefix lengths to match relative to the prefix length N: '{X,Y}' matches
      ## prefix lengths in the inclusive range [X, Y] where N <= X <= Y <= max (max is 32
      ## for IPv4, 128 for IPv6), '{X}' matches exactly length X (equivalent to {X,X}),
      ## '+' is shorthand for {N, max} (the prefix and all more-specific subnets,
      ## including at length N itself; valid even when N is the maximum length). Omit the
      ## suffix to match the prefix exactly at length N.

  MagicBgpRedistributeSources* = ref object of RootObj
    ## Per-source toggles controlling which route sources are redistributed into BGP.
    ## Each property enables redistribution for one route source.
    static_wan*: bool
      ## Redistribute static WAN routes into BGP

