  MconnSnapshot* = ref object of RootObj
    ## Snapshot
    bonds*: Option[seq[MconnSnapshotBond]]
    count_reclaim_failures*: float64
      ## Count of failures to reclaim space
    count_reclaimed_paths*: float64
      ## Count of reclaimed paths
    count_record_failed*: float64
      ## Count of failed snapshot recordings
    count_transmit_failures*: float64
      ## Count of failed snapshot transmissions
    cpu_count*: Option[float64]
      ## Count of processors/cores
    cpu_pressure_10s*: Option[float64]
      ## Percentage of time over a 10 second window that tasks were stalled
    cpu_pressure_300s*: Option[float64]
      ## Percentage of time over a 5 minute window that tasks were stalled
    cpu_pressure_60s*: Option[float64]
      ## Percentage of time over a 1 minute window that tasks were stalled
    cpu_pressure_total_us*: Option[float64]
      ## Total stall time (microseconds)
    cpu_time_guest_ms*: Option[float64]
      ## Time spent running a virtual CPU or guest OS (milliseconds)
    cpu_time_guest_nice_ms*: Option[float64]
      ## Time spent running a niced guest (milliseconds)
    cpu_time_idle_ms*: Option[float64]
      ## Time spent in idle state (milliseconds)
    cpu_time_iowait_ms*: Option[float64]
      ## Time spent wait for I/O to complete (milliseconds)
    cpu_time_irq_ms*: Option[float64]
      ## Time spent servicing interrupts (milliseconds)
    cpu_time_nice_ms*: Option[float64]
      ## Time spent in low-priority user mode (milliseconds)
    cpu_time_softirq_ms*: Option[float64]
      ## Time spent servicing softirqs (milliseconds)
    cpu_time_steal_ms*: Option[float64]
      ## Time stolen (milliseconds)
    cpu_time_system_ms*: Option[float64]
      ## Time spent in system mode (milliseconds)
    cpu_time_user_ms*: Option[float64]
      ## Time spent in user mode (milliseconds)
    delta*: Option[float64]
      ## Number of network operations applied during state transition
    dhcp_leases*: Option[seq[MconnSnapshotDhcpLease]]
    disks*: Option[seq[MconnSnapshotDisk]]
    epsilon*: Option[float64]
      ## Simulated number of network operations applied during state transition
    ha_state*: Option[string]
      ## Name of high availability state
    ha_value*: Option[float64]
      ## Numeric value associated with high availability state (0 = disabled, 1 = active,
      ## 2 = standby, 3 = stopped, 4 = fault)
    interfaces*: Option[seq[MconnSnapshotInterface]]
    io_pressure_full_10s*: Option[float64]
      ## Percentage of time over a 10 second window that all tasks were stalled
    io_pressure_full_300s*: Option[float64]
      ## Percentage of time over a 5 minute window that all tasks were stalled
    io_pressure_full_60s*: Option[float64]
      ## Percentage of time over a 1 minute window that all tasks were stalled
    io_pressure_full_total_us*: Option[float64]
      ## Total stall time (microseconds)
    io_pressure_some_10s*: Option[float64]
      ## Percentage of time over a 10 second window that some tasks were stalled
    io_pressure_some_300s*: Option[float64]
      ## Percentage of time over a 3 minute window that some tasks were stalled
    io_pressure_some_60s*: Option[float64]
      ## Percentage of time over a 1 minute window that some tasks were stalled
    io_pressure_some_total_us*: Option[float64]
      ## Total stall time (microseconds)
    kernel_btime*: Option[float64]
      ## Boot time (seconds since Unix epoch)
    kernel_ctxt*: Option[float64]
      ## Number of context switches that the system underwent
    kernel_processes*: Option[float64]
      ## Number of forks since boot
    kernel_processes_blocked*: Option[float64]
      ## Number of processes blocked waiting for I/O
    kernel_processes_running*: Option[float64]
      ## Number of processes in runnable state
    load_average_15m*: Option[float64]
      ## The fifteen-minute load average
    load_average_1m*: Option[float64]
      ## The one-minute load average
    load_average_5m*: Option[float64]
      ## The five-minute load average
    load_average_cur*: Option[float64]
      ## Number of currently runnable kernel scheduling entities
