    scenario*: WorkersExportsReconciliationScenario

  WorkersExportsReconciliationRename* = ref object of RootObj
    ## A single applied `renamed` tombstone.
    `from`*: string
      ## The original (source) class name.
    to*: string
      ## The new class name (`renamed_to`).

  WorkersExportsReconciliationResult* = ref object of RootObj
    ## Summary of what the declarative exports reconciliation did on this
    ## upload. Present only on uploads that included an `exports` block.
    ## Reconciliation acts on Durable Object entries; `type: worker`
    ## entries in the same map do not participate. Every array is always
    ## present (possibly empty) so clients can iterate unconditionally.
    ## Clients should surface `warnings` prominently, render `info` at
    ## lower visibility, and use `removable_entries` as the "safe to
    ## delete from your config" hint.
    ##
    created*: seq[string]
      ## Class names for which a new namespace was provisioned.
    deleted*: seq[string]
      ## Class names whose namespace was deleted by a `deleted` tombstone.
    info*: seq[WorkersExportsReconciliationInfo]
      ## Non-blocking info entries (stale tombstones, tombstone applied
      ## with class still in code). See `exports_reconciliation_info`.
      ##
    removable_entries*: seq[string]
      ## Source class names whose tombstone entry is now stale and safe
      ## to delete from `exports` (no remaining referencing scripts).
      ##
    renamed*: seq[WorkersExportsReconciliationRename]
      ## Applied `renamed` tombstones.
    transfer_pending*: seq[WorkersExportsReconciliationTransferPending]
      ## Phase-1 transfer hints recorded on the target side.
    transferred*: seq[WorkersExportsReconciliationTransfer]
      ## Committed `transferred` tombstones (phase-2).
    updated*: seq[string]
      ## Class names whose provisioned namespace was mutated in place.
    warnings*: seq[WorkersExportsReconciliationWarning]
      ## Non-blocking warnings. See `exports_reconciliation_warning`.

  WorkersExportsReconciliationScenario* = enum
    ## Stable, machine-readable tag identifying which reconciliation
    ## scenario produced an error, warning, or info entry. Clients may
    ## branch on this value instead of parsing `message`.
    ##
    codeClassNotInExports = "code_class_not_in_exports"
    provisionedClassMissingFromConfig = "provisioned_class_missing_from_config"
    configExportNotInCode = "config_export_not_in_code"
    configReferencesNonexistentClass = "config_references_nonexistent_class"
    orphanedProvisionedNamespace = "orphaned_provisioned_namespace"
    storageTypeMismatch = "storage_type_mismatch"
    freeTierRequiresSqlite = "free_tier_requires_sqlite"
    invalidExport = "invalid_export"
    tombstoneDeleteClassStillInCode = "tombstone_delete_class_still_in_code"
    tombstoneDeleteBlockedByExternalBindings = "tombstone_delete_blocked_by_external_bindings"
    tombstoneRenamedToOccupied = "tombstone_renamed_to_occupied"
    transferredPendingNotFound = "transferred_pending_not_found"
    transferredTargetMissing = "transferred_target_missing"
    transferredTargetMismatch = "transferred_target_mismatch"
    phaseOneTransferSourceMissing = "phase_one_transfer_source_missing"
    phaseOneTransferSourceNamespaceMissing = "phase_one_transfer_source_namespace_missing"
    phaseOneTransferTargetClassProvisioned = "phase_one_transfer_target_class_provisioned"
    phaseOneTransferAfterCommitMismatch = "phase_one_transfer_after_commit_mismatch"
    phaseOneTransferDuplicate = "phase_one_transfer_duplicate"
    phaseOneTransferTargetInDispatchNamespace = "phase_one_transfer_target_in_dispatch_namespace"
    phaseOneTransferSourceInDispatchNamespace = "phase_one_transfer_source_in_dispatch_namespace"
    transferredSourceInDispatchNamespace = "transferred_source_in_dispatch_namespace"
    transferredTargetInDispatchNamespace = "transferred_target_in_dispatch_namespace"
    containerUndeclaredReference = "container_undeclared_reference"
    containerClassNotDurableObject = "container_class_not_durable_object"
    containerWiringInconsistent = "container_wiring_inconsistent"
    containerMultipleDurableObjects = "container_multiple_durable_objects"
    transferContainerParityMismatch = "transfer_container_parity_mismatch"
    transferContainerParityMismatchOnCommit = "transfer_container_parity_mismatch_on_commit"
    tombstoneClassStillInCode = "tombstone_class_still_in_code"
    staleTombstone = "stale_tombstone"
    transferReceiveAlreadyApplied = "transfer_receive_already_applied"
    transferReceiveCleanupComplete = "transfer_receive_cleanup_complete"

